import { mkdir, writeFile } from "node:fs/promises";
import { CAPABILITY_DEFINITIONS } from "../src/capabilities";
import { PERMISSION_DEFINITIONS, permissionNames } from "../src/permissions";
import { SCOPE_DEFINITIONS, scopeNames } from "../src/scopes";

function cell(value: string): string {
  return value.replace(/\|/g, "\\|").replace(/\r?\n/g, " ");
}

const scopeLines: string[] = [
  "# Scope matrix",
  "",
  "This file is generated by `bun run docs`. Do not edit it by hand.",
  "",
  "## Classic scopes",
  "",
  "| Scope | Risk | Category | Capabilities | Description |",
  "| --- | --- | --- | --- | --- |",
];

for (const name of scopeNames()) {
  const scope = SCOPE_DEFINITIONS[name];
  if (!scope) continue;
  scopeLines.push(
    `| \`${scope.name}\` | ${scope.severity} | ${scope.category} | ${scope.capabilities.map((capability) => `\`${capability}\``).join(", ")} | ${cell(scope.description)} |`,
  );
}

scopeLines.push(
  "",
  "## Capabilities",
  "",
  "| Capability | Risk | Category | Classic scopes | Fine-grained permissions | Description |",
  "| --- | --- | --- | --- | --- | --- |",
);

for (const capability of CAPABILITY_DEFINITIONS) {
  scopeLines.push(
    `| \`${capability.id}\` — ${cell(capability.title)} | ${capability.severity} | ${capability.category} | ${capability.scopes.map((scope) => `\`${scope}\``).join(", ")} | ${capability.permissions.map((permission) => `\`${permission}\``).join(", ")} | ${cell(capability.description)} |`,
  );
}

scopeLines.push(
  "",
  "## Scoring",
  "",
  "| Severity | Weight | Minimum score floor |",
  "| --- | --- | --- |",
  "| critical | 50 | 70 |",
  "| high | 20 | 45 |",
  "| medium | 8 | 20 |",
  "| low | 2 | 0 |",
  "",
  "The score is capped at 100. The value is the greater of the weighted sum and the floor for the highest-severity capability. See `src/score.ts` for the implementation.",
  "",
);

const permissionLines: string[] = [
  "# Fine-grained permission matrix",
  "",
  "This file is generated by `bun run docs`. Do not edit it by hand.",
  "",
  "Fine-grained permissions are self-reported with `--permissions`; GitHub does not expose a token's permissions through the API.",
  "",
  "Names are namespaced by resource. Short names such as `contents` are accepted when they are unambiguous.",
  "",
  "| Permission | Title | Access | Category | Read capabilities | Write capabilities | Description |",
  "| --- | --- | --- | --- | --- | --- | --- |",
];

for (const name of permissionNames()) {
  const permission = PERMISSION_DEFINITIONS[name];
  if (!permission) continue;
  permissionLines.push(
    `| \`${permission.name}\` | ${cell(permission.title)} | ${permission.access.join(", ")} | ${permission.category} | ${permission.readCapabilities.map((capability) => `\`${capability}\``).join(", ")} | ${permission.writeCapabilities.map((capability) => `\`${capability}\``).join(", ")} | ${cell(permission.description)} |`,
  );
}

permissionLines.push("");

await mkdir("docs", { recursive: true });
await writeFile("docs/scope-matrix.md", `${scopeLines.join("\n")}\n`, "utf8");
await writeFile("docs/permission-matrix.md", `${permissionLines.join("\n")}\n`, "utf8");
console.log("Wrote docs/scope-matrix.md and docs/permission-matrix.md");
